module vga_ctrl(
input wire pixel_clk,
output wire hsync,
output wire vsync,
output wire [9:0] pixel_x,
output wire [9:0] pixel_y,
output wire visible_region
); 

parameter [31:0] total_pixels=640;
parameter [31:0] sync_pulses=10;
parameter [31:0] blanking_pixels=10;
parameter [31:0] hsync_pulses=10;
parameter [31:0] vsync_pulses=10;
  reg [9:0] hcount;
  reg [9:0] vcount;
  reg hsync;
  reg vsync;
  wire [9:0] pixel_x;
  wire [9:0] pixel_y;
  wire visible_region;
  assign pixel_x = hcount;
  assign pixel_y = vcount;
  assign hsync = hcount > (total_pixels - sync_pulses - hsync_pulses);
  assign vsync = vcount > (total_pixels - sync_pulses - blanking_pixels - vsync_pulses);
  assign visible_region = vcount > (total_pixels - sync_pulses - blanking_pixels) && hcount > (total_pixels - sync_pulses - hsync_pulses);
  always @(posedge pixel_clk) begin
    if(hcount == (total_pixels - sync_pulses - hsync_pulses)) begin
      hcount <= 0;
    end
    else begin
      hcount <= hcount + 1;
    end
  end
  always @(posedge pixel_clk) begin
    if(vcount == (total_pixels - sync_pulses - blanking_pixels)) begin
      vcount <= 0;
    end
    else begin
      vcount <= vcount + 1;
    end
  end
endmodule

