module spdr_uart_framer
(
    input clk_50,
    input rst,

    output reg tx_busy,
    input tx_vld,
    input [7:0] tx_data,

    output rx_vld,
    output [7:0] rx_data,
    output reg rx_frame_error,

    output uart_tx,
    input uart_rx
);
parameter sampling_clk_divider = 100000000/1250000;

reg [7:0] tx_sr;
reg [3:0] tx_cnt;
reg tx_busy_reg;

reg [7:0] rx_sr;
reg [3:0] rx_cnt;
reg rx_vld_reg;
reg rx_frame_error_reg;

always @(posedge clk_50) begin
    if (rst) begin
        tx_busy_reg <= 0;
        tx_cnt <= 0;
        tx_sr <= 0;
    end else begin
        if (tx_busy_reg) begin
            if (tx_cnt == 7) begin
                tx_busy_reg <= 0;
                tx_cnt <= 0;
                tx_sr <= 0;
            end else begin
                tx_sr <= {tx_sr[6:0], tx_vld};
                tx_cnt <= tx_cnt + 1;
            end
        end else begin
            if (tx_vld) begin
                tx_busy_reg <= 1;
                tx_cnt <= 0;
                tx_sr <= tx_data;
            end
        end
    end
end

always @(posedge clk_50) begin
    if (rst) begin
        rx_vld_reg <= 0;
        rx_cnt <= 0;
        rx_sr <= 0;
        rx_frame_error_reg <= 0;
    end else begin
        if (rx_vld_reg) begin
            if (rx_cnt == 7) begin
                rx_vld_reg <= 0;
                rx_cnt <= 0;
                rx_sr <= 0;
            end else begin
                rx_sr <= {rx_sr[6:0], uart_rx};
                rx_cnt <= rx_cnt + 1;
            end
        end else begin
            if (uart_rx) begin
                rx_vld_reg <= 1;
                rx_cnt <= 0;
                rx_sr <= {rx_sr[6:0], uart_rx};
            end
        end
    end
end

always @(posedge clk_50) begin
    if (rst) begin
        rx_frame_error_reg <= 0;
    end else begin
        if (rx_vld_reg) begin
            if (rx_cnt == 7) begin
                if (rx_sr[7:4] != 4'b0000) begin
                    rx_frame_error_reg <= 1;
                end else begin
                    rx_frame_error_reg <= 0;
                end
            end else begin
                if (rx_sr[7:4] != 4'b0000) begin
                    rx_frame_error_reg <= 1;
                end else begin
                    rx_frame_error_reg <= 0;
                end
            end
        end
    end
end

assign uart_tx = tx_sr[0];
assign rx_data = rx_sr[7:0];
assign rx_vld = rx_vld_reg;
assign rx_frame_error = rx_frame_error_reg;

endmodule

