module toe_s_axis_listen_port_req_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam [1:0]
  ZERO = 2'b00,
  ONE  = 2'b01,
  TWO  = 2'b10;

reg  [N-1:0] data_p1;
reg  [N-1:0] data_p2;
reg  [1:0]   state;
reg  [1:0]   next;

assign s_ready = (state == ONE || state == TWO);
assign m_data  = data_p1;
assign m_valid = (state == TWO);

always @(posedge clk) begin
    if (reset) begin
        data_p1 <= {N{1'b0}};
        data_p2 <= {N{1'b0}};
        state  <= ZERO;
    end else begin
        state <= next;
        data_p1 <= data_p2;
        if (state == ONE) begin
            data_p2 <= s_data;
        end else if (state == TWO) begin
            data_p2 <= {N{1'b0}};
        end
    end
end

always @(*) begin
    case (state)
        ZERO:
            if (s_valid & s_ready)
                next = ONE;
            else
                next = ZERO;
        ONE:
            if (s_valid & s_ready)
                next = TWO;
            else if (m_ready)
                next = ZERO;
            else
                next = ONE;
        TWO:
            if (m_ready)
                next = ZERO;
            else
                next = TWO;
        default:
            next = ZERO;
    endcase
end

endmodule

