module AXI_WRITE_DATA_CHANNEL_model(
input wire clk,
input wire resetn,
input wire [31:0] data,
input wire go,
output reg done,
output wire [31:0] WDATA,
output reg [3:0] WSTRB,
output reg WVALID,
input wire WREADY
); 

parameter [31:0] NUM_STATE=4;
reg [31:0] current_state;
reg [31:0] next_state;
  always @(posedge clk, posedge resetn) begin
    if((resetn == 1'b0)) begin
      current_state <= 0;
    end else begin
      current_state <= next_state;
    end
  end
  always @(current_state, go, WREADY) begin
    case(current_state)
    0 : begin
      if((go == 1'b1)) begin
        next_state <= 1;
      end
      else begin
        next_state <= 0;
      end
    end
    1 : begin
      if((WREADY == 1'b1)) begin
        next_state <= 2;
      end
      else begin
        next_state <= 1;
      end
    end
    2 : begin
      if((WREADY == 1'b0)) begin
        next_state <= 2;
      end
      else begin
        next_state <= 3;
      end
    end
    3 : begin
      if((WREADY == 1'b0)) begin
        next_state <= 3;
      end
      else begin
        next_state <= 4;
      end
    end
    4 : begin
      if((WREADY == 1'b0)) begin
        next_state <= 4;
      end
      else begin
        next_state <= 0;
      end
    end
    default : begin
      next_state <= 0;
    end
    endcase
  end
  always @(current_state, data, WSTRB, WVALID) begin
    case(current_state)
    0 : begin
      done <= 1'b0;
      WDATA <= 32'h00000000;
      WSTRB <= 4'h0;
      WVALID <= 1'b0;
    end
    1 : begin
      done <= 1'b0;
      WDATA <= data;
      WSTRB <= WSTRB;
      WVALID <= 1'b1;
    end
    2 : begin
      done <= 1'b0;
      WDATA <= 32'h00000000;
      WSTRB <= 4'h0;
      WVALID <= 1'b0;
    end
    3 : begin
      done <= 1'b0;
      WDATA <= 32'h00000000;
      WSTRB <= 4'h0;
      WVALID <= 1'b0;
    end
    4 : begin
      done <= 1'b1;
      WDATA <= 32'h00000000;
      WSTRB <= 4'h0;
      WVALID <= 1'b0;
    end
    default : begin
      done <= 1'b0;
      WDATA <= 32'h00000000;
      WSTRB <= 4'h0;
      WVALID <= 1'b0;
    end
