module fifo36_demux
  #(parameter match_data = 0,
    parameter match_mask = 0)
   (input clk, input reset, input clear,
    input [35:0] data_i, input src_rdy_i, output dst_rdy_o,
    output [35:0] data0_o, output src0_rdy_o, input dst0_rdy_i,
    output [35:0] data1_o, output src1_rdy_o, input dst1_rdy_i);
reg [1:0] state;
   reg src0_rdy, src1_rdy;
   reg eof;
   wire [35:0] data0_o, data1_o;
   assign data0_o = (state == 2'b00) ? data_i : 0;
   assign data1_o = (state == 2'b01) ? data_i : 0;
   assign src0_rdy_o = (state == 2'b00) ? src_rdy_i : 0;
   assign src1_rdy_o = (state == 2'b01) ? src_rdy_i : 0;
   assign dst_rdy_o = (state == 2'b00) ? dst0_rdy_i : dst1_rdy_i;
   always @(posedge clk) begin
      if (reset) begin
         state <= 2'b00;
         src0_rdy <= 0;
         src1_rdy <= 0;
         eof <= 0;
      end else if (clear) begin
         state <= 2'b00;
         src0_rdy <= 0;
         src1_rdy <= 0;
         eof <= 0;
      end else begin
         case (state)
            2'b00: begin
               if (match_data == data_i[35:0] && match_mask == data_i[35:0]) begin
                  state <= 2'b01;
                  src0_rdy <= 1;
                  src1_rdy <= 0;
                  eof <= 0;
               end else if (dst0_rdy_i) begin
                  state <= 2'b00;
                  src0_rdy <= 0;
                  src1_rdy <= 0;
                  eof <= 0;
               end else if (dst1_rdy_i) begin
                  state <= 2'b01;
                  src0_rdy <= 0;
                  src1_rdy <= 1;
                  eof <= 0;
               end else if (eof) begin
                  state <= 2'b00;
                  src0_rdy <= 0;
                  src1_rdy <= 0;
                  eof <= 1;
               end else begin
                  state <= 2'b00;
                  src0_rdy <= 0;
                  src1_rdy <= 0;
                  eof <= 0;
               end
            end
            2'b01: begin
               if (dst0_rdy_i) begin
                  state <= 2'b00;
                  src0_rdy <= 0;
                  src1_rdy <= 0;
                  eof <= 0;
               end else if (dst1_rdy_i) begin
                  state <= 2'b01;
                  src0_rdy <= 0;
                  src1_rdy <= 1;
                  eof <= 0;
               end else if (eof) begin
                  state <= 2'b00;
                  src0_rdy <= 0;
                  src1_rdy <= 0;
                  eof <= 1;
               end else begin
                  state <= 2'b01;
                  src0_rdy <= 0;
                  src1_rdy <= 1;
                  eof <= 0;
               end
            end
            default: begin
               state <= 2'b00;
               src0_rdy <= 0;
               src1_rdy <= 0;
               eof <= 0;
            end
         endcase
      end
   end
endmodule

module branch_ctrl(
	input [31:0]	data_rs1	,
	input [31:0]	data_rs2	,
	input [2:0]		funct3		,
	output	reg		jmpb
);
always @(*) begin
		case (funct3)
			4'b000: jmpb = (data_rs1 == data_rs2);
			4'b001: jmpb = (data_rs1 != data_rs2);
			4'b010: jmpb = (data_rs1 < data_rs2);
			4'b011: jmpb = (data_rs1 > data_rs2);
			4'b100: jmpb = (data_rs1 < data_rs2) ^ (data_rs1[31] ^ data_rs2[31]);
			4'b101: jmpb = (data_rs1 > data_rs2) ^ (data_rs1[31] ^ data_rs2[31]);
			default: jmpb = 1'b0;
		endcase
	end
endmodule

