        if (dig[9]) uni <= 9;
        else if (dig[8]) uni <= 8;
        else if (dig[7]) uni <= 7;
        else if (dig[6]) uni <= 6;
        else if (dig[5]) uni <= 5;
        else if (dig[4]) uni <= 4;
        else if (dig[3]) uni <= 3;
        else if (dig[2]) uni <= 2;
        else if (dig[1]) uni <= 1;
        else uni <= 0;
    end
end
endmodule

