module Data_Memory(
	input reset,
	input [31:0] address,
	input [31:0] write_data,
	input memRead,
	input memWrite,
	input [2:0] func3,
	output reg [31:0] read_data
    );
reg [31:0] mem[0:2**31-1];
initial
begin
	$readmemh("mem.dat", mem);
end
always @(address)
begin
	if (func3 == 3'b000)
		read_data = mem[address];
	else if (func3 == 3'b001)
		read_data = {mem[address], mem[address+1]};
	else if (func3 == 3'b010)
		read_data = {mem[address], mem[address+1], mem[address+2]};
	else if (func3 == 3'b011)
		read_data = {mem[address], mem[address+1], mem[address+2], mem[address+3]};
	else if (func3 == 3'b100)
		read_data = {mem[address], mem[address+1], mem[address+2], mem[address+3], mem[address+4]};
	else if (func3 == 3'b101)
		read_data = {mem[address], mem[address+1], mem[address+2], mem[address+3], mem[address+4], mem[address+5]};
	else if (func3 == 3'b110)
		read_data = {mem[address], mem[address+1], mem[address+2], mem[address+3], mem[address+4], mem[address+5], mem[address+6]};
	else if (func3 == 3'b111)
		read_data = {mem[address], mem[address+1], mem[address+2], mem[address+3], mem[address+4], mem[address+5], mem[address+6], mem[address+7]};
end
always @(memRead, memWrite, address, write_data)
begin
	if (memRead == 1'b1)
		mem[address] <= write_data;
end
endmodule

module UARTTransmitter(
  input        clock,
               reset,
               io_valid,
  input  [7:0] io_bits,
  input        tick,
  output       io_ready,
               tx
);
reg [3:0] state;
  reg [7:0] data;
  assign io_ready = (state == 4'b0000) && (tick == 1'b1);
  assign tx = (state == 4'b0000) ? 1'b0 : data[0];
  always @(posedge clock) begin
    if (reset) begin
      state <= 4'b0000;
      data  <= 8'b00000000;
    end else begin
      if (tick) begin
        if (state == 4'b0000) begin
          if (io_valid) begin
            data <= io_bits;
            state <= 4'b0001;
          end
        end else begin
          if (state == 4'b0001) begin
            data <= data >> 1;
            state <= 4'b0010;
          end else if (state == 4'b0010) begin
            data <= data >> 1;
            state <= 4'b0011;
          end else if (state == 4'b0011) begin
            data <= data >> 1;
            state <= 4'b0100;
          end else if (state == 4'b0100) begin
            data <= data >> 1;
            state <= 4'b0101;
          end else if (state == 4'b0101) begin
            data <= data >> 1;
            state <= 4'b0110;
          end else if (state == 4'b0110) begin
            data <= data >> 1;
            state <= 4'b0111;
          end else if (state == 4'b0111) begin
            data <= data >> 1;
            state <= 4'b1000;
          end else if (state == 4'b1000) begin
            data <= data >> 1;
            state <= 4'b1001;
          end else if (state == 4'b1001) begin
            data <= data >> 1;
            state <= 4'b1010;
          end else if (state == 4'b1010) begin
            data <= data >> 1;
            state <= 4'b1011;
          end else if (state == 4'b1011) begin
            data <= data >> 1;
            state <= 4'b1100;
          end else if (state == 4'b1100) begin
            data <= data >> 1;
            state <= 4'b1101;
          end else if (state == 4'b1101) begin
            data <= data >> 1;
            state <= 4'b1110;
          end else if (state == 4'b1110) begin
            data <= data >> 1;
            state <= 4'b1111;
          end else if (state == 4'b1111) begin
            data <= data >> 1;
            state <= 4'b1111;
          end
        end
      end
    end
  end
endmodule

