module CW_REGISTER(
input wire [2:0] D,
input wire [2:0] A,
input wire WR,
input wire RD,
input wire CLK,
input wire RST,
output wire WCTRL,
output reg [6:0] Y
); 

reg [6:0] reg_data;
reg [6:0] reg_next;
wire [2:0] data;
wire [2:0] addr;
wire wr;
wire rd;
  assign data = reg_data;
  assign addr = A;
  assign wr = WR;
  assign rd = RD;
  assign WCTRL = reg_next[6];
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b1)) begin
      reg_data <= 7'b0000000;
    end else begin
      if((wr == 1'b1)) begin
        reg_data <= reg_next;
      end
    end
  end
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b1)) begin
      reg_next <= 7'b0000000;
    end else begin
      if((rd == 1'b1)) begin
        reg_next <= data;
      end
      else begin
        reg_next <= reg_data;
      end
    end
  end
  always @(reg_data, reg_next) begin
    if((reg_data[6] == 1'b1)) begin
      Y <= 7'b0000000;
    end
    else if((reg_data[5] == 1'b1)) begin
      Y <= 7'b0000001;
    end
    else if((reg_data[4] == 1'b1)) begin
      Y <= 7'b0000010;
    end
    else if((reg_data[3] == 1'b1)) begin
      Y <= 7'b0000100;
    end
    else if((reg_data[2] == 1'b1)) begin
      Y <= 7'b0001000;
    end
    else if((reg_data[1] == 1'b1)) begin
      Y <= 7'b0010000;
    end
    else if((reg_data[0] == 1'b1)) begin
      Y <= 7'b0100000;
    end
    else begin
      Y <= 7'b1000000;
    end
  end
endmodule

