module vga_controller(
input wire RST,
input wire CLK,
output wire H_SYNC,
output wire V_SYNC,
output wire [10:0] X,
output wire [10:0] Y,
output wire DISP_EN
); 

parameter [31:0] H_ACTIVE=1280;
parameter [31:0] H_FRONT_PORCH=16;
parameter [31:0] H_BACK_PORCH=48;
parameter [31:0] H_SYNC_WIDTH=96;
parameter [31:0] H_TOTAL=H_ACTIVE+H_FRONT_PORCH+H_BACK_PORCH;
parameter [31:0] V_ACTIVE=720;
parameter [31:0] V_FRONT_PORCH=10;
parameter [31:0] V_BACK_PORCH=2;
parameter [31:0] V_SYNC_WIDTH=2;
parameter [31:0] V_TOTAL=V_ACTIVE+V_FRONT_PORCH+V_BACK_PORCH;
reg [10:0] X = 0;
reg [10:0] Y = 0;
reg H_SYNC = 1'b0;
reg V_SYNC = 1'b0;
reg DISP_EN = 1'b0;
  always @(posedge CLK, posedge RST) begin
    if((RST == 1'b1)) begin
      X <= 0;
      Y <= 0;
      H_SYNC <= 1'b0;
      V_SYNC <= 1'b0;
      DISP_EN <= 1'b0;
    end else begin
      if((X == H_TOTAL - 1)) begin
        X <= 0;
        if((Y == V_TOTAL - 1)) begin
          Y <= 0;
          DISP_EN <= 1'b1;
        end else begin
          Y <= Y + 1;
          DISP_EN <= 1'b0;
        end
      end else begin
        X <= X + 1;
        DISP_EN <= 1'b0;
      end
      if((X < H_ACTIVE)) begin
        H_SYNC <= 1'b0;
      end else begin
        H_SYNC <= 1'b1;
      end
      if((Y < V_ACTIVE)) begin
        V_SYNC <= 1'b0;
      end else begin
        V_SYNC <= 1'b1;
      end
    end
  end
  assign H_SYNC = H_SYNC;
  assign V_SYNC = V_SYNC;
  assign X = X;
  assign Y = Y;
  assign DISP_EN = DISP_EN;
endmodule

