module ps2controller (
    input reset,
    input i_clock,
    input i_data,
    output scan_ready,
    output [7:0] scan_code
);
reg [7:0] scan_code;
    reg [3:0] counter;
    assign scan_ready = counter == 4'b1111;
    always @(posedge i_clock or posedge reset) begin
        if (reset) begin
            scan_code <= 8'b0;
            counter <= 4'b0;
        end else begin
            if (counter == 4'b1111) begin
                scan_code <= {scan_code[6:0], i_data};
                counter <= 4'b0;
            end else begin
                scan_code <= scan_code;
                counter <= counter + 1'b1;
            end
        end
    end
endmodule

