            src0_valid <= sink_valid[0];
            src0_data <= sink_data;
            src0_channel <= sink_channel;
            src0_startofpacket <= sink_startofpacket;
            src0_endofpacket <= sink_endofpacket;
        end else if (src1_ready == 1'b1) begin
            src1_valid <= sink_valid[1];
            src1_data <= sink_data;
            src1_channel <= sink_channel;
            src1_startofpacket <= sink_startofpacket;
            src1_endofpacket <= sink_endofpacket;
        end
    end




    assign ready_vector[0] = src0_ready;
    assign ready_vector[1] = src1_ready;

    assign sink_ready = |(ready_vector);

endmodule

