module toe_m_axis_rxread_cmd_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam [1:0]
  ZERO = 2'b00,
  ONE  = 2'b01,
  TWO  = 2'b10;

reg  [N-1:0] data_p1;
reg  [N-1:0] data_p2;
wire         load_p1;
wire         load_p2;
wire         load_p1_from_p2;
reg  [1:0]   state;
reg  [1:0]   next;

assign s_ready = (state == ZERO) ? 1'b1 : 1'b0;
assign m_data  = (state == TWO) ? data_p1 : data_p2;
assign m_valid = (state == TWO) ? 1'b1 : 1'b0;

assign load_p1 = s_valid & s_ready;
assign load_p2 = m_ready & m_valid;
assign load_p1_from_p2 = 1'b1;

always @(posedge clk) begin
    if (load_p1) begin
        data_p1 <= s_data;
        state <= ONE;
    end else if (load_p2) begin
        data_p2 <= data_p1;
        state <= TWO;
    end else begin
        state <= state;
    end
end

always @(posedge clk) begin
    if (load_p1_from_p2) begin
        data_p1 <= data_p2;
    end
end

always @(posedge clk) begin
    if (reset) begin
        data_p1 <= {N{1'b0}};
        data_p2 <= {N{1'b0}};
        state   <= ZERO;
    end else begin
        next    <= state;
    end
end

endmodule

