module alu
  (
   alu_src1,
   alu_src2,
   alu_opcode,
   minus_is_zero,
   less_than,
   less_than_unsigned,
   alu_result
   );
input wire [31:0]       alu_src1;
   input wire [31:0]	   alu_src2;
   input wire [3:0]	   alu_opcode;
   output reg [31:0]	   alu_result;
   output reg		   minus_is_zero;
   output reg		   less_than;
   output reg		   less_than_unsigned;
reg [32:0] alu_result_reg;
   always @(alu_src1, alu_src2, alu_opcode)
     begin
	case (alu_opcode)
	  4'b0000: alu_result_reg = alu_src1 + alu_src2;
	  4'b0001: alu_result_reg = alu_src1 - alu_src2;
	  4'b0010: alu_result_reg = alu_src1 | alu_src2;
	  4'b0011: alu_result_reg = alu_src1 & alu_src2;
	  4'b0100: alu_result_reg = alu_src1 ^ alu_src2;
	  4'b0101: alu_result_reg = alu_src1 << alu_src2;
	  4'b0110: alu_result_reg = alu_src1 >> alu_src2;
	  4'b0111: alu_result_reg = alu_src1 >>> alu_src2;
	  4'b1000: alu_result_reg = alu_src1 + alu_src2;
	  4'b1001: alu_result_reg = alu_src1 - alu_src2;
	  4'b1010: alu_result_reg = alu_src1 | alu_src2;
	  4'b1011: alu_result_reg = alu_src1 & alu_src2;
	  4'b1100: alu_result_reg = alu_src1 ^ alu_src2;
	  4'b1101: alu_result_reg = alu_src1 << alu_src2;
	  4'b1110: alu_result_reg = alu_src1 >> alu_src2;
	  4'b1111: alu_result_reg = alu_src1 >>> alu_src2;
	  default: alu_result_reg = 32'h00000000;
	endcase
     end
   always @(alu_result_reg)
