module Math_Divide(
	input CLK, 
	input [31:0] Divisor, 
	input [31:0] Divider,
	output [31:0] result, 
	output [31:0] remainder,
	inout done 
    );
reg [31:0] Divisor_int;
reg [31:0] Divider_int;
reg [31:0] remainder_int;
reg [31:0] result_int;
reg [31:0] counter;
reg done_int;
assign result = result_int;
assign remainder = remainder_int;
assign done = done_int;
always @(posedge CLK)
begin
	if (done_int == 1'b0)
	begin
		Divisor_int = Divisor;
		Divider_int = Divider;
		remainder_int = Divisor;
		result_int = 0;
		counter = 0;
		done_int = 0;
	end
	else
	begin
		if (remainder_int >= Divider_int)
		begin
			remainder_int = remainder_int - Divider_int;
			result_int = result_int + 1;
			counter = counter + 1;
		end
		else
		begin
			done_int = 1;
		end
	end
end
endmodule

