module QueueCompatibility_14( 
  input        clock, 
  input        reset, 
  output       io_enq_ready, 
  input        io_enq_valid, 
  input  [3:0] io_enq_bits_tl_state_size, 
  input  [1:0] io_enq_bits_tl_state_source, 
  input        io_deq_ready, 
  output       io_deq_valid, 
  output [3:0] io_deq_bits_tl_state_size, 
  output [1:0] io_deq_bits_tl_state_source 
);
reg [3:0] queue_state_size;
  reg [1:0] queue_state_source;
  reg maybe_full;
  assign io_enq_ready = 1'b1;
  assign io_deq_valid = maybe_full;
  assign io_deq_bits_tl_state_size = queue_state_size;
  assign io_deq_bits_tl_state_source = queue_state_source;
  always @(posedge clock) begin
    if (reset) begin
      queue_state_size <= 4'h0;
      queue_state_source <= 2'h0;
      maybe_full <= 1'b0;
    end else begin
      if (io_enq_valid && io_enq_ready) begin
        queue_state_size <= io_enq_bits_tl_state_size;
        queue_state_source <= io_enq_bits_tl_state_source;
        maybe_full <= 1'b1;
      end else if (io_deq_valid && io_deq_ready) begin
        maybe_full <= 1'b0;
      end
    end
  end
endmodule

