module udpLoopback_lbRxMetadataIn_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam
    IDLE        = 2'b00,
    LOAD1       = 2'b01,
    LOAD2       = 2'b10;

reg  [1:0]  state;
reg  [N-1:0] data_p1;
reg  [N-1:0] data_p2;
wire         load1;
wire         load2;

assign s_ready = (state == IDLE);
assign m_data  = (state == IDLE) ? data_p1 : data_p2;
assign m_valid = (state == IDLE) ? 1'b0 : 1'b1;

always @(posedge clk) begin
    if (reset) begin
        state    <= IDLE;
        data_p1  <= {N{1'b0}};
        data_p2  <= {N{1'b0}};
    end else begin
        case (state)
            IDLE: begin
                if (s_valid & s_ready) begin
                    data_p1  <= s_data;
                    data_p2  <= s_data;
                    state    <= LOAD1;
                end
            end
            LOAD1: begin
                if (m_ready) begin
                    data_p1  <= s_data;
                    state    <= LOAD2;
                end
            end
            LOAD2: begin
                if (m_ready) begin
                    data_p2  <= s_data;
                    state    <= IDLE;
                end
            end
            default: begin
                state    <= IDLE;
            end
        endcase
    end
end

endmodule

