        if (clk_cnt == BPS_CNT) begin
          clk_cnt <= 0;
          if (tx_cnt == 8) begin
            tx_flag <= 2'b00;
            tx_cnt <= 0;
          end else begin
            tx_cnt <= tx_cnt + 1;
          end
        end else begin
          clk_cnt <= clk_cnt + 1;
        end
        if (tx_cnt == 0) begin
          uart_txd <= 1'b0;
        end else if (tx_cnt == 8) begin
          uart_txd <= 1'b1;
        end else begin
