input reset;
input [31:0]aport;
input [31:0]dxport;
output [31:0]xport;
output [31:0]yport;
output [31:0]uport;
reg [31:0]xport;
reg [31:0]yport;
reg [31:0]uport;
reg [31:0]aport;
reg [31:0]dxport;
reg clk;
reg reset;

always @(posedge clk or posedge reset)
begin
	if (reset == 1'b1)
	begin
		xport <= 32'd0;
