module Barrel15L_16(
    input [13:0] data_i,
    input [1:0] shift_i,
    output reg [16:0] data_o
    );
wire [16:0] tmp;
    always @(data_i, shift_i) begin
        tmp = {{17{data_i[13]}}, data_i};
        case(shift_i)
            0: data_o = tmp;
            1: data_o = tmp << 1;
            2: data_o = tmp << 2;
            3: data_o = tmp << 3;
        endcase
    end
endmodule

module decoder_3to8 
    (input [2:0] a,
     input enable,
     output reg [7:0] y
    );
always @ (a or enable)
    begin
        if (enable == 0)
            y = 8'b00000000;
        else
            case (a)
                3'b000: y = 8'b00000001;
                3'b001: y = 8'b00000010;
                3'b010: y = 8'b00000100;
                3'b011: y = 8'b00001000;
                3'b100: y = 8'b00010000;
                3'b101: y = 8'b00100000;
                3'b110: y = 8'b01000000;
                3'b111: y = 8'b10000000;
                default: y = 8'b00000000;
            endcase
    end
endmodule

module Data_Memory(input clk, rst, MemWrite, MemRead, mem_to_reg,
input [31:0] addr, write_data, output [31:0] read_data);
reg [31:0] mem [0:31];
initial begin
    for (int i = 0; i < 32; i = i + 1)
        mem[i] = 0;
end
always @(posedge clk) begin
    if (MemWrite == 1) begin
        mem[addr] <= write_data;
    end
end
assign read_data = (MemRead == 1) ? mem[addr] : 0;
endmodule

module binary_updown_counter #(parameter BITS = 1)
        (input wire clk, input wire rst, input wire ena,
         input wire updown, output wire [BITS - 1:0] out, output wire ovf);
reg [BITS - 1:0] cnt;
    wire [BITS - 1:0] enable_wires;
    assign out = cnt;
    assign ovf = (cnt == 2 ** BITS - 1) ^ (cnt == 0);
    generate
        genvar i;
        for (i = 0; i < BITS; i = i + 1) begin : gen
            always @(posedge clk, posedge rst) begin
                if (rst) begin
                    cnt[i] <= 0;
                end else if (ena) begin
                    if (updown) begin
                        if (cnt[i] == 2 ** BITS - 1) begin
                            cnt[i] <= 0;
                        end else begin
                            cnt[i] <= cnt[i] + 1;
                        end
                    end else begin
                        if (cnt[i] == 0) begin
                            cnt[i] <= 2 ** BITS - 1;
                        end else begin
                            cnt[i] <= cnt[i] - 1;
                        end
                    end
                end
            end
            assign enable_wires[i] = ena;
        end
    endgenerate
endmodule

module BCD(
		input [15:0] binary,
		output wire [3:0] b,
		output wire [3:0] s,
		output wire [3:0] g,
		output wire [3:0] q
		);
reg [31:0] reg1;
	always @ (reg1)
		begin
			repeat (16)
				begin
					if (reg1[3:0] > 4)
						reg1[3:0] = reg1[3:0] + 3;
					reg1 = reg1 >> 1;
				end
		end
	assign b = reg1[3:0];
	assign s = reg1[7:4];
	assign g = reg1[11:8];
	assign q = reg1[15:12];
endmodule

