module wb_bridge_16_32
  #(parameter AWIDTH=16)
    (input wb_clk, input wb_rst,
     input A_cyc_i, input A_stb_i, input A_we_i, input [3:0] A_sel_i,
     input [AWIDTH-1:0] A_adr_i, input [31:0] A_dat_i, output [31:0] A_dat_o, output A_ack_o,
     output B_cyc_o, output B_stb_o, output B_we_o, output [1:0] B_sel_o,
     output [AWIDTH-1:0] B_adr_o, output [15:0] B_dat_o, input [15:0] B_dat_i, input B_ack_i
     );
reg [15:0] A_dat_r;
  reg [1:0] A_sel_r;
  reg [AWIDTH-1:0] A_adr_r;
  reg A_ack_r;
  reg [1:0] phase;
  reg [15:0] B_dat_r;
  reg B_ack_r;
  reg [1:0] B_sel_r;
  reg [AWIDTH-1:0] B_adr_r;
  reg B_cyc_r;
  reg B_stb_r;
  reg B_we_r;
  always @(posedge wb_clk) begin
    if (wb_rst) begin
      A_dat_r <= 0;
      A_sel_r <= 0;
      A_adr_r <= 0;
      A_ack_r <= 0;
      phase <= 0;
      B_dat_r <= 0;
      B_ack_r <= 0;
      B_sel_r <= 0;
      B_adr_r <= 0;
      B_cyc_r <= 0;
      B_stb_r <= 0;
      B_we_r <= 0;
    end else begin
      if (A_cyc_i && A_stb_i) begin
        if (A_we_i) begin
          A_dat_r <= A_dat_i;
          A_sel_r <= A_sel_i;
          A_adr_r <= A_adr_i;
          A_ack_r <= 1;
        end else begin
          A_ack_r <= 1;
        end
        if (phase == 0) begin
          B_dat_r <= A_dat_r[15:0];
          B_ack_r <= A_ack_r;
          B_sel_r <= A_sel_r;
          B_adr_r <= A_adr_r[AWIDTH-1:1];
          B_cyc_r <= A_cyc_i;
          B_stb_r <= A_stb_i;
          B_we_r <= A_we_i;
          phase <= 1;
        end else begin
          B_dat_r <= A_dat_r[31:16];
          B_ack_r <= A_ack_r;
          B_sel_r <= A_sel_r;
          B_adr_r <= A_adr_r[AWIDTH-1:1];
          B_cyc_r <= A_cyc_i;
          B_stb_r <= A_stb_i;
          B_we_r <= A_we_i;
          phase <= 0;
        end
      end else begin
        A_ack_r <= 0;
        B_ack_r <= 0;
      end
    end
  end
  assign A_dat_o = A_dat_r;
  assign A_ack_o = A_ack_r;
  assign B_cyc_o = B_cyc_r;
  assign B_stb_o = B_stb_r;
  assign B_we_o = B_we_r;
  assign B_sel_o = B_sel_r;
  assign B_adr_o = B_adr_r;
  assign B_dat_o = B_dat_r;
endmodule

