module clk_div(input clk,
					input rst,
					input SW2,
					input SW15,
					input keyReady,
					input [3:0] BTN_OK,
					output reg[31:0]clkdiv,
					output Clk_CPU,
					output reg readn
					);
reg[31:0] counter;
	reg[31:0] step;
	reg auto_clk;
	reg wasReady;

	always @(posedge clk or posedge rst)
	begin
		if(rst)
		begin
			counter <= 0;
			step <= 0;
			auto_clk <= 0;
			wasReady <= 0;
		end
		else
		begin
			if(SW2)
				auto_clk <= 1;
			else
				auto_clk <= 0;
			if(SW15)
				step <= 1;
			else
				step <= 0;
			if(keyReady)
			begin
				if(BTN_OK[0])
					counter <= 1;
				else if(BTN_OK[1])
					counter <= 2;
				else if(BTN_OK[2])
					counter <= 4;
				else if(BTN_OK[3])
					counter <= 8;
				else if(BTN_OK[4])
					counter <= 16;
				else if(BTN_OK[5])
					counter <= 32;
				else if(BTN_OK[6])
					counter <= 64;
				else if(BTN_OK[7])
					counter <= 128;
				else if(BTN_OK[8])
					counter <= 256;
				else if(BTN_OK[9])
					counter <= 512;
				else if(BTN_OK[10])
					counter <= 1024;
				else if(BTN_OK[11])
					counter <= 2048;
				else if(BTN_OK[12])
					counter <= 4096;
				else if(BTN_OK[13])
					counter <= 8192;
				else if(BTN_OK[14])
					counter <= 16384;
				else if(BTN_OK[15])
					counter <= 32768;
				else
					counter <= 0;
				wasReady <= 1;
			end
			else
				wasReady <= 0;
		end
	end

	always @(posedge clk or posedge rst)
	begin
		if(rst)
			readn <= 0;
		else
			if(auto_clk)
				if(wasReady)
					readn <= 1;
				else
					readn <= 0;
			else
				if(step)
					readn <= 1;
				else
					readn <= 0;
	end

	always @(posedge clk or posedge rst)
	begin
		if(rst)
			clkdiv <= 0;
		else
			if(auto_clk)
				clkdiv <= counter;
			else
				clkdiv <= 1;
	end

	assign Clk_CPU = (auto_clk) ? clk : 1;
endmodule

