module toe_m_axis_rx_data_rsp_metadata_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam [1:0]
  ZERO = 2'b00,
  ONE  = 2'b01,
  TWO  = 2'b10;

reg  [N-1:0] data_p1;
reg  [N-1:0] data_p2;
reg          load_p1;
reg          load_p2;
reg          load_p1_from_p2;

reg  [1:0]   state;
reg  [1:0]   next;

assign s_ready = (state == ZERO) ? 1'b1 : 1'b0;
assign m_data  = (state == TWO) ? data_p1 : {((N)-(1)+(1)){1'b0)};
assign m_valid = (state == TWO) ? 1'b1 : 1'b0;

always @(posedge clk) begin
    if (reset == 1'b1) begin
        data_p1 <= {((N)-(1)+(1)){1'b0}};
        data_p2 <= {((N)-(1)+(1)){1'b0}};
        load_p1 <= 1'b0;
        load_p2 <= 1'b0;
        load_p1_from_p2 <= 1'b0;
        state <= ZERO;
    end else begin
        case (state)
            ZERO: begin
                if (s_valid == 1'b1 && s_ready == 1'b1) begin
                    data_p1 <= s_data;
                    data_p2 <= s_data;
                    load_p1 <= 1'b1;
                    load_p2 <= 1'b1;
                    load_p1_from_p2 <= 1'b0;
                    next <= ONE;
                end else begin
                    next <= ZERO;
                end
            end
            ONE: begin
                if (s_valid == 1'b1 && s_ready == 1'b1) begin
                    data_p1 <= s_data;
                    load_p1 <= 1'b1;
                    load_p2 <= 1'b0;
                    load_p1_from_p2 <= 1'b0;
                    next <= TWO;
                } else if (s_valid == 1'b0 && s_ready == 1'b1) begin
                    next <= ZERO;
                } else begin
                    next <= ONE;
                end
            end
            TWO: begin
                if (m_ready == 1'b1) begin
                    data_p1 <= data_p2;
                    load_p1 <= 1'b1;
                    load_p2 <= 1'b0;
                    load_p1_from_p2 <= 1'b1;
                    next <= ZERO;
                } else begin
                    next <= TWO;
                end
            end
            default: next <= ZERO;
        endcase
    end
end

always @(posedge clk) begin
    if (reset == 1'b1) begin
        load_p1 <= 1'b0;
    end else if (load_p1 == 1'b1) begin
        load_p1 <= 1'b0;
        if (load_p1_from_p2 == 1'b1) begin
            data_p1 <= data_p2;
        end
    end
end

always @(posedge clk) begin
    if (reset == 1'b1) begin
        load_p2 <= 1'b0;
    end else if (load_p2 == 1'b1) begin
        load_p2 <= 1'b0;
        data_p2 <= data_p1;
    end
end

always @(posedge clk) begin
    if (reset == 1'b1) begin
        load_p1_from_p2 <= 1'b0;
    end else if (load_p1_from_p2 == 1'b1) begin
        load_p1_from_p2 <= 1'b0;
    end else if (s_valid == 1'b1 && s_ready == 1'b1) begin
        load_p1_from_p2 <= 1'b1;
    end
end

always @(posedge clk) begin
    if (reset == 1'b1) begin
        state <= ZERO;
    end else begin
        state <= next;
    end
end

endmodule

module Incer #(
    parameter DATA_WIDTH = 8
)
(clk,arstn,din,dout,mode);

input clk;
input arstn;
input mode;
input [DATA_WIDTH-1:0]din;
output [DATA_WIDTH-1:0]dout;
reg [DATA_WIDTH-1:0]counter;
reg state;
parameter ADD_STATE = 1'b0;
parameter INC_STATE = 1'b1;
always @(posedge clk or negedge arstn)
begin
    if(!arstn)
    begin
        counter <= 0;
        state <= ADD_STATE;
    end
    else
    begin
        case (state)
            ADD_STATE: begin
                if(mode)
                    counter <= counter + 1;
                else
                    counter <= counter + 2;
                if(mode)
                    state <= INC_STATE;
                else
                    state <= ADD_STATE;
            end
            INC_STATE: begin
                if(!mode)
                    state <= ADD_STATE;
                else
                    counter <= counter + 1;
            end
        endcase
    end
end
assign dout = counter;
endmodule

