module Counter_Controller #(
    parameter   DWIDTH = 7
)(
    input                   clk,
    input                   rst_n,
    input                   start_i,
    input   [DWIDTH-1:0]    cnt_val_i,
    input   [DWIDTH-1:0]    cnt_i,
    output                  run_o,
    output                  done_o
);
localparam   S_IDLE = 0;
    localparam   S_RUN = 1;
    localparam   S_DONE = 2;

    reg   [1:0]           state;
    reg   [1:0]           state_n;
    reg   [DWIDTH-1:0]    cnt_val;
    reg   [DWIDTH-1:0]    cnt_val_n;
    reg                   run;
    reg                   done;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= S_IDLE;
            cnt_val <= 0;
            run <= 0;
            done <= 0;
        end else begin
            state_n <= state;
            cnt_val_n <= cnt_val;
            run <= 0;
            done <= 0;
            state_n <= state;
            case (state)
                S_IDLE: begin
                    if (start_i) begin
                        state_n <= S_RUN;
                        cnt_val_n <= cnt_val_i;
                    end
                end
                S_RUN: begin
                    if (cnt_val == cnt_i) begin
                        state_n <= S_DONE;
                        done <= 1;
                    end
                    run <= 1;
                end
                S_DONE: begin
                    state_n <= S_IDLE;
                    cnt_val_n <= 0;
                    run <= 0;
                    done <= 0;
                end
            endcase
        end
    end

    assign run_o = run;
    assign done_o = done;
    assign cnt_val = cnt_val_n;
endmodule

