module FFlr(
input wire clk,
input wire [31:0] f,
output reg [31:0] g
); 

wire [31:0] len_raw;
wire [31:0] len;
wire [31:0] x_mask;
wire [31:0] incr;
wire [31:0] f_out;
wire [31:0] res;
reg [31:0] f_incr;
  assign len_raw = f[30:23];
  assign len = len_raw == 255 ? 1 : 0;
  assign x_mask = len_raw == 255 ? 1 : 255;
  assign incr = len_raw == 255 ? 1 : 0;
  assign f_out = f[31] == 1'b0 ? f : f_incr;
  assign res = f[31] == 1'b0 ? {f[29:0],1'b0} : {f[29:0],1'b1};
  always @(posedge clk) begin
    f_incr <= f_out;
    g <= res;
  end
endmodule

