module AOI31X1TS (Y, A0, A1, A2, B0);
output Y;
input A0, A1, A2, B0;
and (A1B0, A1, B0);
  and (A2B0, A2, B0);
  and (A0B0, A0, B0);
  and (A0A1B0, A0, A1, B0);
