    specparam
      tplh$A0$Y = 1.0,
      tphl$A0$Y = 1.0,
      tplh$A1$Y = 1.0,
      tphl$A1$Y = 1.0,
      tplh$A2$Y = 1.0,
      tphl$A2$Y = 1.0,
      tplh$B0$Y = 1.0,
      tphl$B0$Y = 1.0;
    if (A0 == 1'b0 && A1 == 1'b0 && A2 == 1'b0)
      (B0 *> Y) = (tplh$B0$Y, tphl$B0$Y);
