      (B0 *> Y) = (tplh$B0$Y, tphl$B0$Y);
    if (A0 == 1'b0 && A1 == 1'b1 && A2 == 1'b0)
      (B0 *> Y) = (tplh$B0$Y, tphl$B0$Y);
    if (A0 == 1'b0 && A1 == 1'b1 && A2 == 1'b1)
      (B0 *> Y) = (tplh$B0$Y, tphl$B0$Y);
