module echo_server_application_m_axis_read_package_reg_slice
#(parameter
    N = 8   
) (

    input  wire         clk,
    input  wire         reset,

    input  wire [N-1:0] s_data,
    input  wire         s_valid,
    output wire         s_ready,

    output wire [N-1:0] m_data,
    output wire         m_valid,
    input  wire         m_ready
);
localparam [1:0]
  ZERO = 2'b00,
  ONE  = 2'b01,
  TWO  = 2'b10;

reg  [N-1:0] data_p1;
reg  [N-1:0] data_p2;
reg  [1:0]   state;
reg  [1:0]   next;
reg          s_ready_t;
wire         load_p1;
wire         load_p2;
wire         load_p1_from_p2;

assign s_ready = s_ready_t;
assign m_data  = data_p1;
assign m_valid = (state == TWO);

assign load_p1 = (state == ZERO && s_valid) ||
                 (state == ONE && s_valid && m_ready);
assign load_p2 = m_ready;
assign load_p1_from_p2 = (state == TWO && s_valid);

always @(posedge clk) begin
    if (load_p1) begin
        data_p1 <= s_data;
        if (load_p1_from_p2)
            data_p1 <= data_p2;
    end
end


always @(posedge clk) begin
    if (load_p2) begin
        data_p2 <= s_data;
    end
end


always @(posedge clk) begin
    if (load_p1_from_p2) begin
        data_p1 <= data_p2;
    end
end


always @(posedge clk) begin
    if (reset)
        state <= ZERO;
    else
        state <= next;
end


always @(*) begin
    next = state;
    s_ready_t = 1'b0;
    case (state)
        ZERO: begin
            if (s_valid & m_ready) begin
                next = ONE;
                s_ready_t = 1'b1;
            end
        end
        ONE: begin
            if (~s_valid & m_ready) begin
                next = TWO;
            end
        end
        TWO: begin
            if (s_valid & ~m_ready) begin
                next = ONE;
            end
        end
        default: begin
        end
    endcase
end

endmodule

