module Data_CrossDomain(
    input clkA,
    input FlagIn_clkA, 
    input clkB,
    output FlagOut_clkB,
	input [7:0] dataA,
	output [7:0] dataB
);
reg FlagToggle_clkA;
    reg [2:0] SyncA_clkB;
    reg clkA_data;
    reg clkB_data;
    assign FlagOut_clkB = SyncA_clkB[2];
    always @(posedge clkA) begin
        FlagToggle_clkA <= FlagIn_clkA;
        if (FlagToggle_clkA == 1'b1) begin
            clkA_data <= dataA;
        end
    end
    always @(posedge clkB) begin
        if (FlagToggle_clkA == 1'b1) begin
            SyncA_clkB <= {SyncA_clkB[1:0], clkA_data};
        end
    end
    always @(posedge clkB) begin
        if (FlagToggle_clkA == 1'b1) begin
            clkB_data <= dataA;
        end
    end
    assign dataB = clkB_data;
endmodule

module gh_delay_programmable_31(
input wire CLK,
input wire rst,
input wire srst,
input wire D,
input wire [4:0] DELAY,
output wire Q
); 

wire [4:0] D_d1;
wire [4:0] D_d2;
wire [4:0] D_d4;
wire [4:0] D_d8;
wire [4:0] D_d16;
wire [4:0] Q_d1;
wire [4:0] Q_d2;
wire [4:0] Q_d4;
wire [4:0] Q_d8;
wire [4:0] Q_d16;
  gh_delay #(
      .DELAY(2))
  delay_1(
      .CLK(CLK),
    .rst(rst),
    .srst(srst),
    .D(D),
    .Q(Q_d1));
  gh_delay #(
      .DELAY(4))
  delay_2(
      .CLK(CLK),
    .rst(rst),
    .srst(srst),
    .D(Q_d1),
    .Q(Q_d2));
  gh_delay #(
      .DELAY(8))
  delay_4(
      .CLK(CLK),
    .rst(rst),
    .srst(srst),
    .D(Q_d2),
    .Q(Q_d4));
  gh_delay #(
      .DELAY(16))
  delay_8(
      .CLK(CLK),
    .rst(rst),
    .srst(srst),
    .D(Q_d4),
    .Q(Q_d8));
  gh_delay #(
      .DELAY(31))
  delay_16(
      .CLK(CLK),
    .rst(rst),
    .srst(srst),
    .D(Q_d8),
    .Q(Q_d16));
  assign Q = DELAY == 5'b00000 ? D : DELAY == 5'b00001 ? Q_d1 : DELAY == 5'b00010 ? Q_d2 : DELAY == 5'b00011 ? Q_d4 : DELAY == 5'b00100 ? Q_d8 : DELAY == 5'b00101 ? Q_d16 : 1'b0;
endmodule

