module testbench;
reg [2:0] A, B;
    wire A_greater, A_equal, A_less;
    integer i, error;

    comparator_3bit comp(A_greater, A_equal, A_less, A, B);

    initial begin
        for (i = 0; i < 100; i = i + 1) begin
            A = $random;
            B = $random;
            if (A_greater !== (A > B)) begin
                $display("Test failed at index %d: A > B expected %b, got %b", i, A_greater, A > B);
                error = error + 1;
            end
            if (A_equal !== (A == B)) begin
                $display("Test failed at index %d: A == B expected %b, got %b", i, A_equal, A == B);
                error = error + 1;
            end
            if (A_less !== (A < B)) begin
                $display("Test failed at index %d: A < B expected %b, got %b", i, A_less, A < B);
                error = error + 1;
            end
        end
        if (error == 0) begin
            $display("All tests passed!");
        end else begin
            $display("Failed %d tests.", error);
        end
    end

endmodule

