module lpm_or (
    data,  
    result 
);


    input  [(lpm_size * lpm_width)-1:0] data;


    output [lpm_width-1:0] result;
parameter lpm_width = 1;
    parameter lpm_size = 1;


    reg  [(lpm_size * lpm_width)-1:0] result;


    initial begin
        if (lpm_width <= 0) begin
            $display("ERROR: lpm_width must be greater than 0");
            $display("ERROR: Aborting");
            $finish;
        end
        if (lpm_size <= 0) begin
            $display("ERROR: lpm_size must be greater than 0");
            $display("ERROR: Aborting");
            $finish;
        end
    end


    always @* begin
        reg  [(lpm_size * lpm_width)-1:0] temp;
        int i, j;
        for (i = 0; i < lpm_width; i = i + 1) begin
            temp = 0;
            for (j = 0; j < lpm_size; j = j + 1) begin
                temp = temp | data[(j * lpm_width) + i];
            end
            result[i] = temp;
        end
    end


endmodule

module freq_divbyeven(
    clk,
    rst_n,
    clk_div
);
    input clk;
    input rst_n;
    output clk_div;
parameter NUM_DIV = 6;
    reg clk_div;
    reg [31:0] cnt;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 0;
            clk_div <= 0;
        end else begin
            if (cnt == (NUM_DIV - 1)) begin
                cnt <= 0;
                clk_div <= ~clk_div;
            end else begin
                cnt <= cnt + 1;
            end
        end
    end
endmodule

