module uart(
    input clk,
    input rst_n,
    input [7:0] data_in,
    input start,
    output reg [7:0] data_out,
    output reg done
);
reg [3:0] state;
    reg [3:0] bit_counter;
    reg [7:0] shift_reg;
    reg parity;
    reg [3:0] next_state;
    reg [3:0] next_bit_counter;
    reg [7:0] next_shift_reg;
    reg next_parity;
    reg next_done;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= 0;
            bit_counter <= 0;
            shift_reg <= 0;
            parity <= 0;
            done <= 0;
        end else begin
            state <= next_state;
            bit_counter <= next_bit_counter;
            shift_reg <= next_shift_reg;
            parity <= next_parity;
            done <= next_done;
        end
    end
    always @(state or bit_counter or shift_reg or parity or done) begin
        next_state = state;
        next_bit_counter = bit_counter;
        next_shift_reg = shift_reg;
        next_parity = parity;
        next_done = done;
        case (state)
            0: begin
                next_state = 1;
                next_bit_counter = 0;
                next_shift_reg = 0;
                next_parity = 0;
                next_done = 0;
            end
            1: begin
                next_state = 2;
                next_bit_counter = 0;
                next_shift_reg = 0;
                next_parity = 0;
                next_done = 0;
            end
            2: begin
                next_state = 3;
                next_bit_counter = 0;
                next_shift_reg = 0;
                next_parity = 0;
                next_done = 0;
            end
            3: begin
                next_state = 4;
                next_bit_counter = 0;
                next_shift_reg = 0;
                next_parity = 0;
                next_done = 0;
            end
            4: begin
                next_state = 0;
                next_bit_counter = 0;
                next_shift_reg = 0;
                next_parity = 0;
                next_done = 0;
            end
            default: begin
                next_state = 0;
                next_bit_counter = 0;
                next_shift_reg = 0;
                next_parity = 0;
                next_done = 0;
            end
        endcase
    end
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            bit_counter <= 0;
        end else begin
            if (state == 0) begin
                bit_counter <= 0;
            end else if (state == 1) begin
                bit_counter <= bit_counter + 1;
            end else if (state == 2) begin
                bit_counter <= bit_counter + 1;
            end else if (state == 3) begin
                bit_counter <= bit_counter + 1;
            end else if (state == 4) begin
                bit_counter <= bit_counter + 1;
            end
        end
    end
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shift_reg <= 0;
        end else begin
            if (state == 0) begin
                shift_reg <= 0;
            end else if (state == 1) begin
                shift_reg <= 0;
            end else if (state == 2) begin
                shift_reg <= shift_reg << 1;
                shift_reg[0] <= data_in[0];
            end else if (state == 3) begin
                shift_reg <= shift_reg << 1;
                shift_reg[0] <= parity;
            end else if (state == 4) begin
                shift_reg <= shift_reg << 1;
                shift_reg[0] <= start;
            end
        end
    end
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            parity <= 0;
        end else begin
            if (state == 0) begin
                parity <= 0;
            end else if (state == 1) begin
                parity <= 0;
            end else if (state == 2) begin
                parity <= 0;
            end else if (state == 3) begin
                parity <= 0;
            end else if (state == 4) begin
                parity <= shift_reg[0] ^ shift_reg[1] ^ shift_reg[2] ^ shift_reg[3] ^ shift_reg[4] ^ shift_reg[5] ^ shift_reg[6] ^ shift_reg[7];
            end
        end
    end
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            done <= 0;
        end else begin
            if (state == 0) begin
                done <= 0;
            end else if (state == 1) begin
                done <= 0;
            end else if (state == 2) begin
                done <= 0;
            end else if (state == 3) begin
                done <= 0;
            end else if (state == 4) begin
                done <= 1;
            end
        end
    end
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            data_out <= 0;
        end else begin
            if (state == 0) begin
                data_out <= 0;
            end else if (state == 1) begin
                data_out <= 0;
            end else if (state == 2) begin
                data_out <= shift_reg[7];
            end else if (state == 3) begin
                data_out <= shift_reg[6];
            end else if (state == 4) begin
                data_out <= shift_reg[5];
            end
        end
    end
endmodule

