module alu(input signed [31:0] x, input signed [31:0] y, input [3:0] alu_ctrl, output reg signed [31:0] result, output reg zero);
always @(x, y, alu_ctrl) begin
        case (alu_ctrl)
            4'b0000: result = x + y;
            4'b0001: result = x - y;
            4'b0010: result = x * y;
            4'b0011: result = x / y;
            4'b0100: result = x & y;
            4'b0101: result = x | y;
            4'b0110: result = x ^ y;
            4'b0111: result = x < y ? 1'b1 : 1'b0;
            4'b1000: result = x == y ? 1'b1 : 1'b0;
            4'b1001: result = x != y ? 1'b1 : 1'b0;
            4'b1010: result = x > y ? 1'b1 : 1'b0;
            4'b1011: result = x >= y ? 1'b1 : 1'b0;
            4'b1100: result = x << y;
            4'b1101: result = x >> y;
            4'b1110: result = x >>> y;
            4'b1111: result = x >>> y;
            default: result = 32'b0;
        endcase
    end
    always @(result) begin
        if (result == 32'b0) zero = 1'b1;
        else zero = 1'b0;
    end
endmodule

