module FIFO_toe_ackDelayFifoReadCount_V_V (
    clk,
    reset,
    if_empty_n,
    if_read_ce,
    if_read,
    if_dout,
    if_full_n,
    if_write_ce,
    if_write,
    if_din);

input clk;
input reset;
output if_empty_n;
input if_read_ce;
input if_read;
output[DATA_WIDTH - 1:0] if_dout;
output if_full_n;
input if_write_ce;
input if_write;
input[DATA_WIDTH - 1:0] if_din;
parameter MEM_STYLE = "shiftreg";
parameter DATA_WIDTH = 32'd1;
parameter ADDR_WIDTH = 32'd5;
parameter DEPTH = 32'd10;

wire[ADDR_WIDTH - 1:0] shiftReg_addr ;
wire[DATA_WIDTH - 1:0] shiftReg_data, shiftReg_q;
reg[ADDR_WIDTH:0] mOutCountR = {(ADDR_WIDTH+1){1'b1}};
reg internal_empty_n = 0, internal_full_n = 1;
reg[ADDR_WIDTH:0] shiftReg_ce = {(ADDR_WIDTH+1){1'b0}};
reg[ADDR_WIDTH:0] readPtrR = 0;
reg[ADDR_WIDTH:0] writePtrR = 0;

assign if_empty_n = internal_empty_n;
assign if_full_n = internal_full_n;
assign shiftReg_data = if_din;
assign if_dout = shiftReg_q;

always @ (posedge clk)
    begin
        if (reset == 1'b1)
        begin
            mOutCountR <= {(ADDR_WIDTH+1){1'b0}};
            internal_empty_n <= 1'b0;
            internal_full_n <= 1'b1;
        end
        else
        begin
            if (((if_write & if_write_ce) == 1 & internal_full_n == 1) == 1)
            begin
                if (writePtrR == (DEPTH - 1))
                    writePtrR <= 0;
                else
                    writePtrR <= writePtrR + 1;
                mOutCountR <= mOutCountR + 1;
                if (mOutCountR == {(ADDR_WIDTH+1){1'b1}})
                    internal_full_n <= 1'b0;
            end
            else if (((if_read & if_read_ce) == 1 & internal_empty_n == 0) == 1)
            begin
                if (readPtrR == (DEPTH - 1))
                    readPtrR <= 0;
                else
                    readPtrR <= readPtrR + 1;
                mOutCountR <= mOutCountR - 1;
                if (mOutCountR == 0)
                    internal_empty_n <= 1'b0;
            end
            if (MEM_STYLE == "shiftreg")
            begin
                shiftReg_addr <= readPtrR;
                shiftReg_ce <= writePtrR - readPtrR;
            end
        end
    end

assign shiftReg_ce = {((ADDR_WIDTH-1)-(0)+1){1'b0}} | shiftReg_ce;

always @ (posedge clk)
    begin
        if (reset == 1'b1)
            shiftReg_data <= {((DATA_WIDTH-1)-(0)+1){1'b0}};
        else if (((if_write & if_write_ce) == 1 & internal_full_n == 0) == 1)
            shiftReg_data <= if_din;
        else
            shiftReg_data <= shiftReg_q;
    end

always @ (posedge clk)
    begin
        if (reset == 1'b1)
            shiftReg_q <= {((DATA_WIDTH-1)-(0)+1){1'b0}};
        else
            shiftReg_q <= shiftReg_data;
    end

endmodule

