module cyclonev_bias_logic (
    clk,
    shiftnld,
    captnupdt,
    mainclk,
    updateclk,
    capture,
    update
    );


input  clk;
input  shiftnld;
input  captnupdt;


output mainclk;
output updateclk;
output capture;
output update;
reg mainclk_tmp;
reg updateclk_tmp;
reg capture_tmp;
reg update_tmp;

always @(posedge clk or posedge captnupdt or posedge shiftnld) begin
    case ({captnupdt, shiftnld})
        2'b00: begin
            mainclk_tmp <= 1'b0;
            updateclk_tmp <= 1'b0;
            capture_tmp <= 1'b0;
            update_tmp <= 1'b0;
        end
        2'b01: begin
            mainclk_tmp <= 1'b0;
            updateclk_tmp <= 1'b0;
            capture_tmp <= 1'b1;
            update_tmp <= 1'b0;
        end
        2'b10: begin
            mainclk_tmp <= 1'b1;
            updateclk_tmp <= 1'b0;
            capture_tmp <= 1'b0;
            update_tmp <= 1'b0;
        end
        2'b11: begin
            mainclk_tmp <= 1'b1;
            updateclk_tmp <= 1'b1;
            capture_tmp <= 1'b0;
            update_tmp <= 1'b0;
        end
        default: begin
            mainclk_tmp <= 1'b0;
            updateclk_tmp <= 1'b0;
            capture_tmp <= 1'b0;
            update_tmp <= 1'b0;
        end
    endcase
end

assign mainclk = mainclk_tmp & 1'b1;
assign updateclk = updateclk_tmp & 1'b1;
assign capture = capture_tmp & 1'b1;
assign update = update_tmp & 1'b1;

endmodule

