module datapath(clk, startGameEn, user_x, user_y, enemy_x, enemy_y, enem_grid, x, y, colour);
input clk; 
	input startGameEn; 
	input [7:0]user_x; 
	input [6:0]user_y; 
	input [7:0]enemy_x; 
	input [6:0]enemy_y; 
	input [160*120-1:0] enem_grid; 
	output reg [7:0] x; 
	output reg [6:0] y; 
	output reg[2:0] colour;
reg clear;
	always @(posedge clk) begin
		if(startGameEn) begin
			x <= 0;
			y <= 0;
			clear <= 1;
		end
		else begin
			if(x == 160 && y == 120) begin
				x <= 0;
				y <= 0;
				clear <= 1;
			end
			else begin
				if(x == user_x && y == user_y) begin
					colour <= 3'b001;
				end
				else if(x == enemy_x && y == enemy_y) begin
					colour <= 3'b010;
				end
				else if(enem_grid[(y*160)+x] == 1'b1) begin
					colour <= 3'b011;
				end
				else begin
					colour <= 3'b000;
				end
				x <= x + 1;
				y <= y + 1;
				clear <= 0;
			end
		end
	end
endmodule

module Start_UP_Handler(
input wire i_CLK,
output wire o_RST
); 

parameter g_Clock_Frequency = 100000000;
parameter g_Initial_Reset_Time = 10000000;
reg r_RST = 1'b1;
reg r_RST_Counter = 0;
  assign o_RST = r_RST;
  always @(posedge i_CLK) begin
    if(r_RST == 1'b1) begin
      r_RST_Counter <= 0;
      r_RST <= 1'b1;
    end
    else if(r_RST_Counter == g_Initial_Reset_Time) begin
      r_RST <= 1'b0;
    end
    else begin
      r_RST_Counter <= r_RST_Counter + 1;
    end
  end
endmodule

module sonar(
input clk, rst_n, 
input do_measure,
input sonar_pulse,
output reg [7:0] inches,
output reg sonar_trigger = 0,
output reg READY = 0
);
reg [3:0] state;
reg [31:0] timeCount;
reg [31:0] timeoutCounter;
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= 0;
        timeCount <= 0;
        timeoutCounter <= 0;
        sonar_trigger <= 0;
        inches <= 0;
        READY <= 0;
    end else begin
        case (state)
            0: begin
                if (do_measure) begin
                    state <= 1;
                    sonar_trigger <= 1;
                end
            end
            1: begin
                if (sonar_pulse) begin
                    state <= 2;
                    timeoutCounter <= 0;
                end
            end
            2: begin
                if (!sonar_pulse) begin
                    state <= 3;
                    timeoutCounter <= 0;
                end
            end
            3: begin
                if (timeoutCounter < 1000000) begin
                    timeoutCounter <= timeoutCounter + 1;
                end else begin
                    timeoutCounter <= 0;
                    timeCount <= timeCount + 1;
                end
            end
            default: begin
                state <= 0;
                timeCount <= 0;
                timeoutCounter <= 0;
                sonar_trigger <= 0;
                inches <= 0;
                READY <= 0;
            end
        endcase
    end
end
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        inches <= 0;
    end else begin
        if (state == 3) begin
            inches <= timeCount * 12 / 1000000;
        end
    end
end
endmodule

