  reg [1:0] state;
  reg s_input_a_ack;
  assign input_a_ack = s_input_a_ack;
  always @(posedge clk) begin
    if (rst) begin
      state <= 0;
      s_input_a_ack <= 0;
    end else begin
      case (state)
        0: begin
          if (input_a_stb) begin
            value <= input_a;
            state <= 1;
            s_input_a_ack <= 1;
