reg [7:0] D;
reg [7:0] E;
reg [7:0] F;
reg [7:0] G;
reg [7:0] H;
  always @(posedge clk) begin
    if(write_i == 1'b1) begin
      case(sel_i)
      3'b000 : begin
        A <= data_in_i;
