        E <= data_in_i;
      end
      3'b101 : begin
        F <= data_in_i;
      end
      3'b110 : begin
        G <= data_in_i;
      end
      3'b111 : begin
        H <= data_in_i;
      end
      default : begin
      end
      endcase
    end
  end
  adder_seq adder_seq1(
      A,
    B,
    C,
    D,
    E,
    F,
    G,
    H,
    data_out_o);
endmodule

