module BaudTickGen(
	input clk, enable,
	output tick  
);
parameter ClkFrequency = 100000000;
	parameter Baud = 115200;
	parameter Oversampling = 1;
	
	assign tick = (Acc == (Baud * Oversampling - 1)) ? 1'b1 : 1'b0;
	
	reg [31:0] Acc = 0;
	reg [31:0] Inc = 0;
	
	assign Inc = (Baud * Oversampling - 1) << (31 - log2(Baud * Oversampling));
	
	assign log2 = $clog2(Baud * Oversampling);
	
	always @(posedge clk) begin
		if (enable) begin
			Acc <= Acc + Inc;
		end else begin
			Acc <= 0;
		end
	end
	
endmodule

