module vga_sync_pulse
(
    input   i_clk,
    output  o_hsync,
    output  o_vsync,
    output reg [9:0] o_col_count = 0,
    output reg [9:0] o_row_count = 0
);
parameter COLUMNS = 1280;
    parameter ROWS = 720;
    parameter ACTIVE_COLUMNS = 640;
    parameter ACTIVE_ROWS = 480;
    assign o_hsync = (o_col_count >= (COLUMNS - ACTIVE_COLUMNS)) ? 1'b0 : 1'b1;
    assign o_vsync = (o_row_count >= (ROWS - ACTIVE_ROWS)) ? 1'b0 : 1'b1;
    always @(posedge i_clk) begin
        if (o_col_count >= (COLUMNS - ACTIVE_COLUMNS)) begin
            o_col_count <= 0;
        end else begin
            o_col_count <= o_col_count + 1;
        end
        if (o_row_count >= (ROWS - ACTIVE_ROWS)) begin
            o_row_count <= 0;
        end else begin
            o_row_count <= o_row_count + 1;
        end
    end
endmodule

