module db (
        input clk, n_reset, button_in,
        output reg out
    );
parameter maxbit = 10;
    reg [maxbit-1:0] q_reg, q_next;
    reg q_add, q_reset;
    reg f1, f2;
    always @(posedge clk or negedge n_reset) begin
        if (!n_reset) begin
            q_reg <= 0;
            q_add <= 0;
            q_reset <= 0;
        end else begin
            q_reg <= q_next;
            q_add <= 1;
            q_reset <= 0;
        end
    end
    always @(posedge clk or negedge n_reset) begin
        if (!n_reset) begin
            f1 <= 0;
            f2 <= 0;
        end else begin
            f1 <= button_in;
            f2 <= f1;
        end
    end
    always @(posedge clk or negedge n_reset) begin
        if (!n_reset) begin
            q_next <= 0;
        end else begin
            if (q_add) begin
                if (q_reg == (2**maxbit-1)) begin
                    q_next <= 0;
                end else begin
                    q_next <= q_reg + 1;
                end
            end else begin
                if (q_reset) begin
                    q_next <= 0;
                end else begin
                    q_next <= q_reg;
                end
            end
        end
    end
    always @(posedge clk or negedge n_reset) begin
        if (!n_reset) begin
            out <= 0;
        end else begin
            if (q_reg == (2**maxbit-1)) begin
                out <= f2;
            end else begin
                out <= 0;
            end
        end
    end
endmodule

