module Walk2R_example (
	input logic vga_clk,
	input logic [9:0] DrawX, DrawY,
	input logic blank,
	output logic [3:0] red, green, blue
);
logic [12:0] rom_address;
logic [3:0] palette_red, palette_green, palette_blue;

logic [3:0] current_red, current_green, current_blue;

assign rom_address = (DrawX*16/640) + (DrawY*9/480 * 16);

always_ff @ (posedge vga_clk) begin
	current_red <= current_green <= current_blue = 4'h0;
	palette_red <= current_red;
	palette_green <= current_green;
	palette_blue <= current_blue;
end

Walk2R_rom Walk2R_rom (
	.clock   (vga_clk),
	.address (rom_address),
	.q       (palette_red)
);

Walk2R_palette Walk2R_palette (
	.index (palette_red),
	.q     (red, green, blue)
);

assign current_red = blank ? 4'h0 : palette_red;
assign current_green = blank ? 4'h0 : palette_green;
assign current_blue = blank ? 4'h0 : palette_blue;

endmodule

