module cycloneii_latch(D, ENA, PRE, CLR, Q);

   input D;
   input ENA, PRE, CLR;
   output Q;
reg q_out = 0;

   buf(D_in, D);
   buf(ENA_in, ENA);
   buf(PRE_in, PRE);
   buf(CLR_in, CLR);

   assign Q = q_out;

   always @(posedge D_in or posedge ENA_in or posedge PRE_in or posedge CLR_in) begin
      if (CLR_in == 1'b1) begin
         q_out <= 1'b0;
