module barrel_shifter_tb;
reg [7:0] in;
	reg [1:0] control;
	wire [7:0] out;
	reg [31:0] error_count;

	barrel_shifter uut(
		.in(in),
		.control(control),
		.out(out)
	);

	initial begin
		error_count = 0;
		in = 128;
		control = 2'b00;
		#10;
		if (out !== 64) begin
			$display("FAIL: shift by 4, in = 128, out = %d", out);
			error_count = error_count + 1;
		end else begin
			$display("PASS: shift by 4, in = 128, out = %d", out);
		end

		in = 128;
		control = 2'b01;
		#10;
		if (out !== 32) begin
			$display("FAIL: shift by 2, in = 128, out = %d", out);
			error_count = error_count + 1;
		end else begin
			$display("PASS: shift by 2, in = 128, out = %d", out);
		end

		in = 128;
		control = 2'b10;
		#10;
		if (out !== 64) begin
			$display("FAIL: shift by 1, in = 128, out = %d", out);
			error_count = error_count + 1;
		end else begin
			$display("PASS: shift by 1, in = 128, out = %d", out);
		end

		in = 128;
		control = 2'b11;
		#10;
		if (out !== 16) begin
			$display("FAIL: shift by 7, in = 128, out = %d", out);
			error_count = error_count + 1;
		end else begin
			$display("PASS: shift by 7, in = 128, out = %d", out);
		end

		in = 255;
		control = 2'b00;
		#10;
		if (out !== 128) begin
			$display("FAIL: shift by 4, in = 255, out = %d", out);
			error_count = error_count + 1;
		end else begin
			$display("PASS: shift by 4, in = 255, out = %d", out);
		end

		in = 255;
		control = 2'b01;
		#10;
		if (out !== 64) begin
			$display("FAIL: shift by 2, in = 255, out = %d", out);
			error_count = error_count + 1;
		end else begin
			$display("PASS: shift by 2, in = 255, out = %d", out);
		end

		in = 255;
		control = 2'b10;
		#10;
		if (out !== 32) begin
			$display("FAIL: shift by 1, in = 255, out = %d", out);
			error_count = error_count + 1;
		end else begin
			$display("PASS: shift by 1, in = 255, out = %d", out);
		end

		in = 255;
		control = 2'b11;
		#10;
		if (out !== 8) begin
			$display("FAIL: shift by 7, in = 255, out = %d", out);
			error_count = error_count + 1;
		end else begin
			$display("PASS: shift by 7, in = 255, out = %d", out);
		end

		$display("Total errors: %d", error_count);
		$finish;
	end
endmodule

