module delay (
	input clk,
	input reset,
	input [3:0] variable_pulse_index,
	output slow_pulse,
	output fast_pulse,
	output variable_pulse
);
reg [31:0] counter = 0;
	assign slow_pulse = counter > 18000000;
	assign fast_pulse = counter > 4800000;
	assign variable_pulse = counter > variable_pulse_index * 2000000 / 24000000;
	initial begin
		counter = 0;
	end
	always @(posedge clk) begin
		if (reset) begin
			counter = 0;
		end else begin
			counter = counter + 1;
		end
	end
endmodule

