    always @( SCK_in, CPOL, CPHA, idle, S_BaudRate ) begin
        case (CPOL & CPHA)
            2'b00: begin
                Shift_clk = 1'b0;
                Sample_clk = 1'b0;
            end
            2'b01: begin
                Shift_clk = 1'b0;
                Sample_clk = 1'b1;
            end
            2'b10: begin
                Shift_clk = 1'b1;
                Sample_clk = 1'b0;
            end
            2'b11: begin
                Shift_clk = 1'b1;
                Sample_clk = 1'b1;
            end
        endcase
    end
    always @( SCK_in, CPOL, CPHA, idle, S_BaudRate ) begin
        if (idle == 1'b0) begin
            if (S_BaudRate == 1'b1) begin
                S_BaudRate = 1'b1;
            end
            else begin
                S_BaudRate = 1'b0;
            end
        end
        else begin
            S_BaudRate = 1'b0;
        end
    end
endmodule

