module serial(clk, reset, rxD,sout,signal,counter);
input clk;      
input reset;    
input rxD;   

output reg [n-1:0]sout; 
output reg signal;   
output reg [31:0]counter;
parameter n = 30;
parameter count = 4;

reg [2:0]delay;

top top1(clk, reset, rxD, s_in, counter, signal);

always @(posedge clk)
begin
	if (reset == 1'b1)
	begin
		counter <= 0;
		signal <= 0;
		delay <= 0;
	end
	else
	begin
		if (counter == count)
		begin
			signal <= 1;
			delay <= 1;
		end
		else
		begin
			signal <= 0;
			delay <= 0;
		end
		if (delay == 1)
		begin
			sout <= s_in;
			counter <= counter + 1;
		end
		else
		begin
			sout <= 0;
			counter <= 0;
		end
	end
end

endmodule

