module twocmp(input [31:0]A,output [31:0]B);
genvar i;
generate
for(i=0;i<32;i=i+1)
begin
assign B[i]=i==0?A[0]:|({A[0],A[i-1]});
end
endgenerate
endmodule

module arbiter (
clock, 
reset, 
req_0,
req_1, 
gnt_0,
gnt_1
);

input clock, reset, req_0, req_1;
output gnt_0, gnt_1;
reg gnt_0, gnt_1;

always @(posedge clock) begin
	if (reset) begin
		gnt_0 <= 0;
		gnt_1 <= 0;
	end else begin
		if (req_0) begin
			gnt_0 <= 1;
			gnt_1 <= 0;
		end else if (req_1) begin
			gnt_0 <= 0;
			gnt_1 <= 1;
		end else begin
			gnt_0 <= 0;
			gnt_1 <= 0;
		end
	end
end

endmodule

module NAND3C(Y,A,B,C);
 input A,B,C;
 output Y;
wire A__bar,B__bar;
 not	INV_1_0(A__bar,A);
 not	INV_1_1(B__bar,B);
 and	A__5(XA,XB,A__bar,B__bar);
 nand	Y(Y,XA,C);
 endmodule

