module pcm(set,clk,q1,q2,q3);
	input set,clk;
	output q1,q2,q3;
reg [4:0] count;
	always @(posedge clk)
		if(set)
			count <= 9;
		else
			count <= count - 1;
	assign q1 = (count >= 7) & (count <= 9);
	assign q2 = (count >= 4) & (count <= 6);
	assign q3 = (count >= 1) & (count <= 3);
endmodule

module datamemory(
input wire [31:0] Address,
input wire [31:0] WriteData,
input wire MemWrite,
input wire MemRead,
output reg [31:0] ReadData,
output reg [3:0] O_LMotor,
output reg [3:0] O_RMotor,
input wire [6:0] I_Sensors,
output reg [6:0] O_Leds,
input wire [2:0] I_Rf,
output reg O_Buzzer,
output reg [7:0] O_Seg,
output reg [2:0] O_El_7l,
input wire [5:0] I_St_7l,
input wire I_Clock
); 

always @(posedge I_Clock) begin
    if(MemRead == 1'b1) begin
      case(Address)
      32'h00000000 : ReadData <= I_Sensors;
      32'h00000004 : ReadData <= I_Rf;
      32'h00000008 : ReadData <= I_St_7l;
      default : ReadData <= 32'h00000000;
      endcase
    end
  end
  always @(posedge I_Clock) begin
    if(MemWrite == 1'b1) begin
      case(Address)
      32'h00000000 : O_Leds <= WriteData[6:0];
      32'h00000004 : O_LMotor <= WriteData[3:0];
      32'h00000008 : O_RMotor <= WriteData[3:0];
      32'h0000000C : O_Buzzer <= WriteData[0];
      32'h00000010 : O_Seg <= WriteData[7:0];
      32'h00000014 : O_El_7l <= WriteData[2:0];
      default : O_Leds <= 7'h00;
      endcase
    end
  end
endmodule

