module bus_mux (din,sel,dout);

input [TOTAL_DAT-1 : 0] din;
input [SEL_WIDTH-1:0] sel;
output [DAT_WIDTH-1:0] dout;
parameter DAT_WIDTH = 8;
parameter SEL_WIDTH = 2;
parameter TOTAL_DAT = 16;

wire [DAT_WIDTH-1:0] temp[2**SEL_WIDTH-1:0];

genvar i;
generate
for (i = 0; i < 2**SEL_WIDTH; i = i+1) begin
    assign temp[i] = din[DAT_WIDTH*(i+1)-1:DAT_WIDTH*i];
end
endgenerate

assign dout = temp[sel];

endmodule

