module vga_sync(
input wire clk,
input wire rst,
output reg active,
output reg hsync,
output reg vsync,
output wire [9:0] xaddr,
output wire [9:0] yaddr
); 

parameter [31:0] h_size=640;
parameter [31:0] v_size=480;
parameter [31:0] h_front=16;
parameter [31:0] h_back=48;
parameter [31:0] h_retrace=24;
parameter [31:0] v_front=9;
parameter [31:0] v_back=33;
parameter [31:0] v_retrace=6;
reg [31:0] h_count_reg;
reg [31:0] v_count_reg;
  always @(posedge clk) begin
    if(rst == 1'b1) begin
      h_count_reg <= 0;
      v_count_reg <= 0;
    end else begin
      h_count_reg <= h_count_reg + 1;
      v_count_reg <= v_count_reg + 1;
    end
  end
  assign xaddr = h_count_reg;
  assign yaddr = v_count_reg;
  always @(posedge clk) begin
    if(rst == 1'b1) begin
      active <= 1'b0;
      hsync <= 1'b0;
      vsync <= 1'b0;
    end else begin
      if(h_count_reg < (h_size - h_front - h_back - h_retrace)) begin
        active <= 1'b1;
        hsync <= 1'b1;
        vsync <= 1'b1;
      end
      else if(h_count_reg < (h_size - h_front - h_back)) begin
        active <= 1'b1;
        hsync <= 1'b0;
        vsync <= 1'b1;
      end
      else if(h_count_reg < (h_size - h_front)) begin
        active <= 1'b1;
        hsync <= 1'b0;
        vsync <= 1'b0;
      end
      else begin
        active <= 1'b0;
        hsync <= 1'b0;
        vsync <= 1'b0;
      end
    end
  end
endmodule

