                    next_state = 2'b10;
                end
            end
            2'b10: begin
                if (in == 1'b0) begin
                    next_state = 2'b10;
                    out = 0;
                end else begin
                    next_state = 2'b11;
                end
            end
            2'b11: begin
                if (in == 1'b0) begin
                    next_state = 2'b11;
                    out = 1;
                end else begin
                    next_state = 2'b00;
                end
            end
