module TopModule(
    input  clk,
    input  aresetn,
    input  x,
    output z
);
reg [2:0] state;
    reg z_reg;
    always @(posedge clk or negedge aresetn) begin
        if (!arstn) begin
            state <= 3'b000;
            z_reg <= 1'b0;
        end else begin
            case (state)
                3'b000: begin
                    if (x) begin
                        state <= 3'b001;
                        z_reg <= 1'b0;
                    end
                end
                3'b001: begin
                    if (x) begin
                        state <= 3'b010;
                        z_reg <= 1'b0;
                    end
                end
                3'b010: begin
                    if (x) begin
                        state <= 3'b011;
                        z_reg <= 1'b0;
                    end
                    else begin
                        state <= 3'b000;
                        z_reg <= 1'b0;
                    end
                end
                3'b011: begin
                    if (x) begin
                        state <= 3'b011;
                        z_reg <= 1'b0;
                    end
                    else begin
                        state <= 3'b000;
                        z_reg <= 1'b0;
                    end
                end
                3'b100: begin
                    if (x) begin
                        state <= 3'b101;
                        z_reg <= 1'b0;
                    end
                end
                3'b101: begin
                    if (x) begin
                        state <= 3'b110;
                        z_reg <= 1'b0;
                    end
                end
                3'b110: begin
                    if (x) begin
                        state <= 3'b111;
                        z_reg <= 1'b0;
                    end
                    else begin
                        state <= 3'b100;
                        z_reg <= 1'b0;
                    end
                end
                3'b111: begin
                    if (x) begin
                        state <= 3'b111;
                        z_reg <= 1'b0;
                    end
                    else begin
                        state <= 3'b100;
                        z_reg <= 1'b0;
                    end
                end
                default: begin
                    state <= 3'b000;
                    z_reg <= 1'b0;
                end
            endcase
        end
    end
    assign z = z_reg;
endmodule

