module TopModule(
    input  clk,
    input  load,
    input  [255:0] data,
    output reg [255:0] q
);
reg [15:0] neighbours[15:0];
    always @(posedge clk) begin
        if (load) begin
            q <= data;
        end else begin
            for (int i = 0; i < 16; i++) begin
                for (int j = 0; j < 16; j++) begin
                    neighbours[i][j] = 0;
                    for (int k = -1; k <= 1; k++) begin
                        for (int l = -1; l <= 1; l++) begin
                            if (k == 0 && l == 0) begin
                                neighbours[i][j] += 0;
                            end else begin
                                neighbours[i][j] += q[(i+k)%16 + (j+l)%16];
                            end
                        end
                    end
                    if (neighbours[i][j] == 0) begin
                        q[i*16+j] <= 0;
                    end else if (neighbours[i][j] == 1) begin
                        q[i*16+j] <= 1;
                    end else if (neighbours[i][j] == 2) begin
                        q[i*16+j] <= q[i*16+j];
                    end else if (neighbours[i][j] == 3) begin
                        q[i*16+j] <= 1;
                    end else if (neighbours[i][j] == 4) begin
                        q[i*16+j] <= 0;
                    end
                end
            end
        end
    end
