    predict_valid,
    predict_pc (7 bits),
    predict_taken,
    predict_history (7 bits),

    train_valid,
    train_taken,
    train_mispredicted,
    train_history (7 bits),
    train_pc (7 bits)
);

input  clk;
input  areset;

input  predict_valid;
input  [6:0] predict_pc;
output predict_taken;
output [6:0] predict_history;

input  train_valid;
input  train_taken;
input  train_mispredicted;
input  [6:0] train_history;
input  [6:0] train_pc;

assign predict_taken = (predict_valid == 1) ? 1'b1 : 1'b0;
assign predict_history = (predict_valid == 1) ? train_history : 7'b0;

reg [6:0] branch_history;
reg [6:0] pht [127:0];

always @(posedge clk) begin
    if (train_valid == 1) begin
        pht[train_pc] <= train_history;
        if (train_mispredicted == 1) begin
            branch_history <= train_history;
        end
    end
end

always @(posedge clk) begin
    if (predict_valid == 1) begin
        branch_history <= pht[predict_pc];
    end
end

endmodule

module TopModule(
    input  clk,
    input  reset,
    input  [7:0] in,
    output reg [23:0] out_bytes,
    output reg done
);
reg [1:0] state;
    always @(posedge clk) begin
        if (reset) begin
            state <= 0;
            done <= 0;
        end else begin
            case (state)
                0: begin
                    if (in[3]) begin
                        state <= 1;
                        done <= 0;
                    end
                end
                1: begin
                    if (in[3]) begin
                        state <= 2;
                        done <= 0;
                    end
                end
                2: begin
                    if (in[3]) begin
                        state <= 3;
                        done <= 0;
                    end
                end
                3: begin
                    if (in[3]) begin
                        state <= 0;
                        done <= 1;
                    end
                end
                default: begin
                    state <= 0;
                    done <= 0;
                end
            endcase
        end
    end
    always @(posedge clk) begin
        if (done) begin
            out_bytes <= {in[7:0], 16'b0};
        end else begin
            out_bytes <= {out_bytes[23:16], in[7:0]};
        end
    end
endmodule

