module TopModule (
  input clk,
  input areset,
  input train_valid,
  input train_taken,
  output logic [1:0] state
);
logic [1:0] next_state;
  always_ff @(posedge clk) begin
    if (arst) begin
      state <= 2'b01;
    end else if (train_valid) begin
      if (train_taken) begin
        next_state <= state + 1;
      end else begin
        next_state <= state - 1;
      end
    end
  end
  always_comb begin
    state = next_state;
  end
endmodule

module TopModule (
  input a,
  input b,
  input c,
  input d,
  output out,
  output out_n
);
wire and1_out;
  wire and2_out;
  wire or1_out;

  and and1 (and1_out, a, b);
  and and2 (and2_out, c, d);
  or or1 (or1_out, and1_out, and2_out);
  not not1 (out_n, or1_out);
  assign out = or1_out;

endmodule

