  end
endmodule

module TopModule (
  input in,
  input [3:0] state,
  output reg [3:0] next_state,
  output out
);
always @(state, in) begin
    case (state)
      4'b0001: begin
        next_state = 4'b0001;
        out = 1'b0;
      end
      4'b0010: begin
        next_state = 4'b0010;
        out = 1'b0;
      end
      4'b0100: begin
        next_state = 4'b0100;
        out = 1'b0;
      end
      4'b1000: begin
        next_state = 4'b0100;
        out = 1'b1;
      end
    endcase
  end
endmodule

module TopModule (
  input clk,
  input load,
  input [9:0] data,
  output tc
);
reg [9:0] count;
  reg tc;
  always @(posedge clk) begin
    if (load) begin
      count <= data;
      tc <= 0;
    end else begin
      if (count == 0) begin
        tc <= 1;
      end else begin
        count <= count - 1;
        tc <= 0;
      end
    end
  end
endmodule

